# Generated by deployify. Do not edit manually; 'deployify generate' rewrites it.
#
# Drives IIS for Deployify's IIS target. Deployify runs it locally with -Action and writes the
# request (JSON) to standard input; secrets and the connection password travel that way, never
# on the command line or in a file. The script opens a PowerShell remoting session to the
# server (WinRM or SSH) or, with no host, works on this machine, and prints one result line:
#   ##deployify {json}
#
# Compatible with Windows PowerShell 5.1 and PowerShell 7.

[CmdletBinding()]
param(
    [Parameter(Mandatory = $true)]
    [ValidateSet('Ping', 'List', 'Apply', 'Activate', 'Health', 'Delete')]
    [string]$Action
)

$ErrorActionPreference = 'Stop'
$ProgressPreference = 'SilentlyContinue'

# ---------------------------------------------------------------------------------------------
# Runs on the IIS server, in the remoting session or locally. Returns '##result {json}'.
# ---------------------------------------------------------------------------------------------
$server = {
    param([string]$ServerAction, [string]$RequestJson)

    $ErrorActionPreference = 'Stop'
    $ProgressPreference = 'SilentlyContinue'
    $request = $RequestJson | ConvertFrom-Json
    $root = $request.sitesRoot
    $markerName = 'deployify.json'

    function Get-ServerManager {
        $dll = Join-Path $env:windir 'system32\inetsrv\Microsoft.Web.Administration.dll'
        if (-not (Test-Path $dll)) {
            throw "IIS management is not installed on $env:COMPUTERNAME ($dll is missing). Install the Web-Server and Web-Scripting-Tools features."
        }
        Add-Type -Path $dll
        return New-Object Microsoft.Web.Administration.ServerManager
    }

    function Read-Marker([string]$dir) {
        $path = Join-Path $dir $markerName
        if (Test-Path $path) { return (Get-Content -Raw -Path $path | ConvertFrom-Json) }
        return $null
    }

    function Get-PhysicalPath($sm, [string]$siteName) {
        $site = $sm.Sites[$siteName]
        if ($null -eq $site) { return $null }
        return [Environment]::ExpandEnvironmentVariables($site.Applications['/'].VirtualDirectories['/'].PhysicalPath)
    }

    function Convert-Thumbprint([string]$hex) {
        $bytes = New-Object byte[] ($hex.Length / 2)
        for ($i = 0; $i -lt $bytes.Length; $i++) { $bytes[$i] = [Convert]::ToByte($hex.Substring($i * 2, 2), 16) }
        return ,$bytes
    }

    function Out-Result($value) {
        return '##result ' + (ConvertTo-Json -InputObject $value -Depth 10 -Compress)
    }

    function Get-ReleasePath([string]$serviceDir, [string]$release) {
        return Join-Path (Join-Path $serviceDir 'releases') $release
    }

    # Points the site at $releasePath with the given settings, creating the pool and site when
    # missing, then starts or recycles them so the app picks everything up.
    function Set-Site($sm, $site, $secrets, [string]$releasePath) {
        if (@($site.bindings).Count -eq 0) { throw "$($site.service) has no http binding; IIS can only host web apps." }

        # Application pool: no managed runtime (the ASP.NET Core Module hosts .NET).
        $pool = $sm.ApplicationPools[$site.siteName]
        if ($null -eq $pool) { $pool = $sm.ApplicationPools.Add($site.siteName) }
        $pool.ManagedRuntimeVersion = ''
        $pool.ProcessModel.IdentityType = [Microsoft.Web.Administration.ProcessModelIdentityType]$site.appPoolIdentity
        if ($site.alwaysRunning) {
            $pool.StartMode = [Microsoft.Web.Administration.StartMode]::AlwaysRunning
            $pool.ProcessModel.IdleTimeout = [TimeSpan]::Zero
        } else {
            $pool.StartMode = [Microsoft.Web.Administration.StartMode]::OnDemand
        }

        $first = @($site.bindings)[0]
        $iisSite = $sm.Sites[$site.siteName]
        if ($null -eq $iisSite) {
            $iisSite = $sm.Sites.Add($site.siteName, 'http', "*:$($first.port):$($first.hostName)", $releasePath)
        }
        $app = $iisSite.Applications['/']
        $app.ApplicationPoolName = $site.siteName
        $app.VirtualDirectories['/'].PhysicalPath = $releasePath
        try { $app.SetAttributeValue('preloadEnabled', [bool]$site.alwaysRunning) } catch { }
        $iisSite.ServerAutoStart = $true

        $iisSite.Bindings.Clear()
        foreach ($b in @($site.bindings)) {
            $info = "*:$($b.port):$($b.hostName)"
            if ($b.protocol -eq 'https') {
                $added = $iisSite.Bindings.Add($info, (Convert-Thumbprint $site.certificateThumbprint), $site.certificateStore)
                if ($b.hostName) { $added.SetAttributeValue('sslFlags', 1) }
            } else {
                $iisSite.Bindings.Add($info, 'http') | Out-Null
            }
        }

        # Environment variables, kept in applicationHost.config (admins only), not in the app folder.
        try {
            $section = $sm.GetApplicationHostConfiguration().GetSection('system.webServer/aspNetCore', $site.siteName)
        } catch {
            throw "The ASP.NET Core Module is not installed on $env:COMPUTERNAME. Install the ASP.NET Core Hosting Bundle."
        }
        $vars = $section.GetCollection('environmentVariables')
        $vars.Clear()
        $all = @()
        if ($site.env) { $all += @($site.env.PSObject.Properties) }
        if ($secrets) { $all += @($secrets.PSObject.Properties) }
        foreach ($p in $all) {
            $element = $vars.CreateElement('environmentVariable')
            $element.SetAttributeValue('name', $p.Name)
            $element.SetAttributeValue('value', [string]$p.Value)
            $vars.Add($element) | Out-Null
        }

        $sm.CommitChanges()

        $sm = Get-ServerManager
        try {
            $pool = $sm.ApplicationPools[$site.siteName]
            if ($pool.State -eq [Microsoft.Web.Administration.ObjectState]::Started) { $pool.Recycle() | Out-Null } else { $pool.Start() | Out-Null }
            $iisSite = $sm.Sites[$site.siteName]
            if ($iisSite.State -ne [Microsoft.Web.Administration.ObjectState]::Started) { $iisSite.Start() | Out-Null }
        } catch {
            throw "IIS saved '$($site.siteName)' but could not start it: $($_.Exception.Message)"
        }
    }

    function Write-Marker([string]$serviceDir, $site) {
        [pscustomobject]@{
            managedBy   = 'deployify'
            service     = $site.service
            environment = $site.environment
            siteName    = $site.siteName
            fingerprint = $site.fingerprint
            release     = $site.release
            deployedAt  = (Get-Date).ToUniversalTime().ToString('o')
        } | ConvertTo-Json | Set-Content -Path (Join-Path $serviceDir $markerName) -Encoding UTF8
    }

    # Each release's settings (secrets included), so a rollback restores them with its files.
    # The folder is readable by Administrators and SYSTEM only, like applicationHost.config.
    function Save-Settings([string]$serviceDir, $site, $secrets) {
        $dir = Join-Path $serviceDir 'settings'
        if (-not (Test-Path $dir)) {
            New-Item -ItemType Directory -Force -Path $dir | Out-Null
            $acl = New-Object System.Security.AccessControl.DirectorySecurity
            $acl.SetAccessRuleProtection($true, $false)
            foreach ($sid in 'S-1-5-32-544', 'S-1-5-18') {
                $rule = New-Object System.Security.AccessControl.FileSystemAccessRule(
                    (New-Object System.Security.Principal.SecurityIdentifier($sid)), 'FullControl',
                    'ContainerInherit, ObjectInherit', 'None', 'Allow')
                $acl.AddAccessRule($rule)
            }
            Set-Acl -Path $dir -AclObject $acl
        }
        $saved = [pscustomobject]@{ site = $site; secrets = $secrets }
        ConvertTo-Json -InputObject $saved -Depth 20 | Set-Content -Path (Join-Path $dir "$($site.release).json") -Encoding UTF8
    }

    function Read-Settings([string]$serviceDir, [string]$release) {
        $path = Join-Path (Join-Path $serviceDir 'settings') "$release.json"
        if (-not (Test-Path $path)) { return $null }
        return (Get-Content -Raw -Path $path | ConvertFrom-Json)
    }

    # Keeps the newest releases and their settings; one still locked by a recycling worker goes next time.
    function Remove-OldReleases([string]$serviceDir, [string]$current, [int]$keep) {
        Get-ChildItem -Path (Join-Path $serviceDir 'releases') -Directory |
            Where-Object { $_.Name -ne $current } |
            Sort-Object CreationTimeUtc -Descending |
            Select-Object -Skip ([Math]::Max(0, $keep - 1)) |
            ForEach-Object { try { Remove-Item -Path $_.FullName -Recurse -Force } catch { } }
        $settingsDir = Join-Path $serviceDir 'settings'
        if (Test-Path $settingsDir) {
            Get-ChildItem -Path $settingsDir -Filter '*.json' |
                Where-Object { -not (Test-Path (Get-ReleasePath $serviceDir $_.BaseName)) } |
                ForEach-Object { try { Remove-Item -Path $_.FullName -Force } catch { } }
        }
    }

    # One HTTP request to the site on this server; returns the status code (null when no response) and the start of the body.
    function Get-HttpStatus([string]$url) {
        $request = [System.Net.WebRequest]::Create($url)
        $request.Timeout = 10000
        $request.AllowAutoRedirect = $false
        $response = $null
        try {
            $response = $request.GetResponse()
        } catch {
            $ex = $_.Exception
            while ($null -ne $ex -and -not ($ex -is [System.Net.WebException])) { $ex = $ex.InnerException }
            if ($null -eq $ex -or $null -eq $ex.Response) {
                $message = $_.Exception.Message
                if ($null -ne $ex) { $message = $ex.Message }
                return [pscustomobject]@{ code = $null; body = ''; error = $message }
            }
            $response = $ex.Response
        }
        try {
            $reader = New-Object System.IO.StreamReader($response.GetResponseStream())
            $buffer = New-Object char[] 65536
            $read = $reader.Read($buffer, 0, $buffer.Length)
            return [pscustomobject]@{ code = [int]$response.StatusCode; body = [string]::new($buffer, 0, [Math]::Max(0, $read)); error = $null }
        } finally {
            $response.Close()
        }
    }

    switch ($ServerAction) {
        'Ping' {
            $principal = New-Object Security.Principal.WindowsPrincipal([Security.Principal.WindowsIdentity]::GetCurrent())
            $inetStp = Get-ItemProperty -Path 'HKLM:\SOFTWARE\Microsoft\InetStp' -ErrorAction SilentlyContinue
            $ancm = Test-Path (Join-Path $env:ProgramFiles 'IIS\Asp.Net Core Module\V2\aspnetcorev2.dll')
            $mwa = Test-Path (Join-Path $env:windir 'system32\inetsrv\Microsoft.Web.Administration.dll')
            $version = $null
            if ($inetStp) { $version = $inetStp.VersionString }
            return Out-Result ([pscustomobject]@{
                computer   = $env:COMPUTERNAME
                iisVersion = $version
                management = $mwa
                aspNetCore = $ancm
                admin      = $principal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)
            })
        }

        'List' {
            $services = @()
            if (Test-Path $root) {
                $sm = Get-ServerManager
                foreach ($dir in Get-ChildItem -Path $root -Directory) {
                    $marker = Read-Marker $dir.FullName
                    if ($null -eq $marker -or $marker.managedBy -ne 'deployify') { continue }
                    $services += [pscustomobject]@{
                        service     = $marker.service
                        environment = $marker.environment
                        siteName    = $marker.siteName
                        fingerprint = $marker.fingerprint
                        release     = $marker.release
                        siteExists  = ($null -ne $sm.Sites[$marker.siteName])
                    }
                }
            }
            return Out-Result ([pscustomobject]@{ services = $services })
        }

        'Prepare' {
            # Makes an empty release folder for the package, unless the site already runs from it.
            $site = $request.site
            $release = Join-Path (Join-Path (Join-Path $root $site.siteName) 'releases') $site.release
            $current = $null
            try { $current = Get-PhysicalPath (Get-ServerManager) $site.siteName } catch { }
            if ((Test-Path $release) -and $current -eq $release) {
                return Out-Result ([pscustomobject]@{ releasePath = $release; needsCopy = $false })
            }
            if (Test-Path $release) { Remove-Item -Path $release -Recurse -Force }
            New-Item -ItemType Directory -Force -Path $release | Out-Null
            return Out-Result ([pscustomobject]@{ releasePath = $release; needsCopy = $true })
        }

        'Apply' {
            $site = $request.site
            $serviceDir = Join-Path $root $site.siteName
            $release = Get-ReleasePath $serviceDir $site.release
            if (-not (Test-Path (Join-Path $release '*'))) { throw "Release folder $release is empty; the package was not copied." }

            $existing = Read-Marker $serviceDir
            $sm = Get-ServerManager
            if ($null -eq $existing -and $null -ne $sm.Sites[$site.siteName]) {
                throw "IIS site '$($site.siteName)' already exists and was not deployed by Deployify; rename it or set iis.siteNamePrefix."
            }
            if ($null -ne $existing -and $existing.fingerprint -eq $site.fingerprint -and (Get-PhysicalPath $sm $site.siteName) -eq $release) {
                return Out-Result ([pscustomobject]@{ siteName = $site.siteName; release = $site.release; changed = $false })
            }

            Save-Settings $serviceDir $site $request.secrets
            Set-Site $sm $site $request.secrets $release
            Write-Marker $serviceDir $site
            Remove-OldReleases $serviceDir $site.release ([int]$site.keepReleases)
            return Out-Result ([pscustomobject]@{ siteName = $site.siteName; release = $site.release; changed = $true })
        }

        'Activate' {
            # Rollback: put the site back on a release still on the server, with that release's settings.
            $serviceDir = Join-Path $root $request.siteName
            $release = Get-ReleasePath $serviceDir $request.release
            $marker = Read-Marker $serviceDir
            if ($null -eq $marker -or $marker.managedBy -ne 'deployify') {
                throw "'$($request.siteName)' was not deployed by Deployify on $env:COMPUTERNAME."
            }
            $saved = Read-Settings $serviceDir $request.release
            if (-not (Test-Path (Join-Path $release '*')) -or $null -eq $saved) {
                throw "Release $($request.release) of '$($request.siteName)' is no longer on $env:COMPUTERNAME (only the newest iis.keepReleases are kept)."
            }

            $sm = Get-ServerManager
            if ($marker.release -eq $request.release -and (Get-PhysicalPath $sm $request.siteName) -eq $release) {
                return Out-Result ([pscustomobject]@{ siteName = $request.siteName; release = $request.release; changed = $false })
            }

            Set-Site $sm $saved.site $saved.secrets $release
            Write-Marker $serviceDir $saved.site
            return Out-Result ([pscustomobject]@{ siteName = $request.siteName; release = $request.release; changed = $true })
        }

        'Health' {
            $siteName = $request.siteName
            $marker = Read-Marker (Join-Path $root $siteName)
            function Out-Health([string]$state, [string]$detail) {
                return Out-Result ([pscustomobject]@{ state = $state; detail = $detail })
            }

            if ($null -eq $marker) { return Out-Health 'failed' "'$siteName' is not deployed" }
            if ($marker.release -ne $request.release) {
                return Out-Health 'failed' "'$siteName' runs release $($marker.release), not $($request.release)"
            }

            $sm = Get-ServerManager
            $iisSite = $sm.Sites[$siteName]
            $pool = $sm.ApplicationPools[$siteName]
            if ($null -eq $iisSite -or $null -eq $pool) { return Out-Health 'failed' "the IIS site or application pool '$siteName' is gone" }
            try {
                $poolState = $pool.State
                $siteState = $iisSite.State
            } catch {
                return Out-Health 'progressing' "IIS did not report the state of '$siteName': $($_.Exception.Message)"
            }
            if ($poolState -eq [Microsoft.Web.Administration.ObjectState]::Stopped) {
                return Out-Health 'failed' "application pool '$siteName' stopped (rapid-fail protection: the app keeps crashing)"
            }
            if ($siteState -eq [Microsoft.Web.Administration.ObjectState]::Stopped) {
                return Out-Health 'failed' "site '$siteName' is stopped (is one of its ports in use by something else?)"
            }
            if ($poolState -ne [Microsoft.Web.Administration.ObjectState]::Started -or $siteState -ne [Microsoft.Web.Administration.ObjectState]::Started) {
                return Out-Health 'progressing' "site $siteState, application pool $poolState"
            }

            $port = $null
            foreach ($b in $iisSite.Bindings) {
                $parts = $b.BindingInformation.Split(':')
                if ($b.Protocol -eq 'http' -and $parts.Length -ge 3 -and -not $parts[2]) { $port = $parts[1]; break }
            }
            if ($null -eq $port) { return Out-Health 'failed' "'$siteName' has no http binding to check" }

            $path = [string]$request.healthPath
            if (-not $path.StartsWith('/')) { $path = '/' + $path }
            $url = "http://localhost:$port$path"
            $response = Get-HttpStatus $url
            if ($null -eq $response.code) { return Out-Health 'progressing' "no response from $url yet ($($response.error))" }
            # The ASP.NET Core Module's own error pages: the app failed to start, and won't on its own.
            if ($response.body -match 'HTTP Error (500\.3\d|502\.5)') {
                return Out-Health 'failed' "the app failed to start (HTTP Error $($Matches[1]) from $url); see the Application event log"
            }
            if ($response.code -lt 500) { return Out-Health 'healthy' "HTTP $($response.code) from $url" }
            return Out-Health 'progressing' "HTTP $($response.code) from $url"
        }

        'Delete' {
            $siteName = $request.siteName
            $serviceDir = Join-Path $root $siteName
            $removed = @()
            $marker = Read-Marker $serviceDir
            $sm = Get-ServerManager
            if ($null -eq $marker -or $marker.managedBy -ne 'deployify') {
                if ($null -ne $sm.Sites[$siteName]) {
                    throw "IIS site '$siteName' was not deployed by Deployify; leaving it alone."
                }
                return Out-Result ([pscustomobject]@{ removed = $removed })
            }

            $iisSite = $sm.Sites[$siteName]
            if ($null -ne $iisSite) {
                try { $iisSite.Stop() | Out-Null } catch { }
                $sm.Sites.Remove($iisSite)
                $removed += "site $siteName"
            }
            $pool = $sm.ApplicationPools[$siteName]
            if ($null -ne $pool) {
                try { $pool.Stop() | Out-Null } catch { }
                $sm.ApplicationPools.Remove($pool)
                $removed += "application pool $siteName"
            }
            try { $sm.GetApplicationHostConfiguration().RemoveLocationPath($siteName) } catch { }
            $sm.CommitChanges()

            # The worker process may hold files for a moment after the pool stops.
            for ($i = 1; $i -le 5; $i++) {
                try { Remove-Item -Path $serviceDir -Recurse -Force; break }
                catch { if ($i -eq 5) { throw "Removed '$siteName' from IIS but not its folder $($serviceDir): $($_.Exception.Message)" }; Start-Sleep -Seconds 2 }
            }
            $removed += "folder $serviceDir"
            return Out-Result ([pscustomobject]@{ removed = $removed })
        }

        default { throw "Unknown action $ServerAction" }
    }
}

# ---------------------------------------------------------------------------------------------
# Runs where Deployify runs: opens the session and copies the package.
# ---------------------------------------------------------------------------------------------
$session = $null
try {
    $request = [Console]::In.ReadToEnd() | ConvertFrom-Json
    $connection = $request.connection
    $request.PSObject.Properties.Remove('connection')
    $packagePath = $request.packagePath
    $serverJson = ConvertTo-Json -InputObject $request -Depth 20 -Compress

    if ($connection.host) {
        $options = @{ ErrorAction = 'Stop' }
        if ($connection.transport -eq 'Ssh') {
            $options.HostName = $connection.host
            if ($connection.userName) { $options.UserName = $connection.userName }
            if ($connection.keyFilePath) { $options.KeyFilePath = $connection.keyFilePath }
            if ($connection.port) { $options.Port = [int]$connection.port }
        } else {
            $options.ComputerName = $connection.host
            if ($connection.useSsl) { $options.UseSSL = $true }
            if ($connection.port) { $options.Port = [int]$connection.port }
            if ($connection.userName) {
                if (-not $connection.password) { throw "iis.userName is set but no password was found (iis.password or IIS_PASSWORD)." }
                $secure = ConvertTo-SecureString -String $connection.password -AsPlainText -Force
                $options.Credential = New-Object System.Management.Automation.PSCredential($connection.userName, $secure)
            }
        }
        $session = New-PSSession @options
    }

    function Invoke-Server([string]$serverAction) {
        if ($null -ne $session) {
            $output = Invoke-Command -Session $session -ScriptBlock $server -ArgumentList $serverAction, $serverJson
        } else {
            $output = & $server $serverAction $serverJson
        }
        $line = @($output) | Where-Object { $_ -is [string] -and $_.StartsWith('##result ') } | Select-Object -Last 1
        if ($null -eq $line) { throw "The server returned no result for $serverAction." }
        return $line.Substring(9)
    }

    if ($Action -eq 'Apply') {
        $prepared = Invoke-Server 'Prepare' | ConvertFrom-Json
        if ($prepared.needsCopy) {
            $source = Join-Path $packagePath '*'
            if ($null -ne $session) {
                Copy-Item -Path $source -Destination $prepared.releasePath -ToSession $session -Recurse -Force
            } else {
                Copy-Item -Path $source -Destination $prepared.releasePath -Recurse -Force
            }
        }
    }

    Write-Output ('##deployify ' + (Invoke-Server $Action))
    exit 0
}
catch {
    [Console]::Error.WriteLine($_.Exception.Message)
    exit 1
}
finally {
    if ($null -ne $session) { Remove-PSSession -Session $session }
}
